                while True:
                    reply = terminal.read(game.deadline)
                    if reply.timed_out:
                        outcome = game.expire(question.id, reply.at)
                    elif reply.text is None:
                        game.stop()
                        break
                    else:
                        outcome = game.submit(question.id, reply.text, reply.at)
